/* eslint-disable @typescript-eslint/naming-convention */
import { Component, OnInit, ViewChild } from '@angular/core';
import { CourseService } from '../../../../data/service/course/course.service';
import { CourseFilterComponent } from '../../../components/modal/filter/course-filter/course-filter.component';
import { GResponse } from '../../../../core/common/GResponse';
import { CourseFilterModel, ICourseFilterModel } from '../../../../data/model/course/CourseFilterModel';
import { ActivatedRoute, Router } from '@angular/router';
import { ModalController, IonRouterOutlet, IonContent } from '@ionic/angular';
import { G } from '../../../../core/common/G';
import { SafeUrl } from '@angular/platform-browser';

@Component({
  selector: 'app-off-priced-courses',
  templateUrl: './off-priced-courses.component.html',
  styleUrls: ['./off-priced-courses.component.scss']
})
export class OffPricedCoursesComponent implements OnInit {

  @ViewChild(IonContent) content: IonContent;

  filteredCourses: ICourseFilterModel;
  showSearchbar = false;
  queryText = '';
  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';

  constructor(
    private activatedRoute: ActivatedRoute,
    private courseService: CourseService,
    private router: Router,
    public modalCtrl: ModalController,
    public routerOutlet: IonRouterOutlet) { }

  goTop() {
    this.content.scrollToTop(3000);
  }

  ngOnInit(): void {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;

    this.showSearchbar = false;
    this.queryText = '';

    let filter: ICourseFilterModel;

    this.activatedRoute.queryParams.subscribe(params => {

      const page = params.page;

      if (page === undefined) {
        filter = new CourseFilterModel(false);
      } else {

        const take = params.take ? params.take : null;
        const title = params.title ? params.title : null;
        const startPrice = params.startPrice ? params.startPrice : null;
        const endPrice = params.endPrice ? params.endPrice : null;
        const categoryIds = params.categoryIds ? params.categoryIds : [];
        const sortId = params.sortId ? params.sortId : 4;

        if (
          startPrice == null &&
          endPrice == null &&
          categoryIds == null &&
          sortId == null) {

          filter = new CourseFilterModel(false, page, take, title);
        } else {
          filter =
            new CourseFilterModel(true, page, take, title, startPrice, endPrice, categoryIds, sortId);
        }
      }
      this.filteredCourses = filter;

      this.courseService.GetHomeOffPricedCoursesByFilter(filter).subscribe(
        res => {
          if (res.status === GResponse.SuccessStatus) {
            this.filteredCourses = res.data;
          } else {

          }
        },
        err => {  }
      );
    });
  }

  forwardUrl(url: string) {
    window.location.href = url;
  }

  onSort(sortId: string | number) {

    this.filteredCourses.sortId = +sortId;
    this.setQueryParams(1);
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  setFilter() {
    // change filteredCourses
    this.filteredCourses.takeEntity = 8;
    this.setQueryParams(1);
  }

  goPreviousPage() {

    if (this.filteredCourses.startPage == null) {
      return;
    }
    if (this.filteredCourses.pageId > this.filteredCourses.startPage && +this.filteredCourses.pageId - 1 > 0) {
      this.setQueryParams(+this.filteredCourses.pageId - 1);
    }
  }

  goNextPage() {

    if (this.filteredCourses.endPage == null) {
      return;
    }
    if (this.filteredCourses.pageId < this.filteredCourses.endPage) {
      this.setQueryParams(+this.filteredCourses.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  clearFilter() {
    this.router.navigate(['Course', 'OffPricedCourses']);
  }

  private setQueryParams(pageId: number) {

    this.content.scrollToTop(1500);

    this.router
      .navigate(
        ['Course', 'OffPricedCourses'],
        {
          queryParams:
          {
            page: pageId < 1 ? 1 : pageId,
            take: this.filteredCourses.takeEntity ? this.filteredCourses.takeEntity : null,
            title: this.filteredCourses.title ? this.filteredCourses.title : null,
            startPrice: this.filteredCourses.startPrice ? this.filteredCourses.startPrice : null,
            endPrice: this.filteredCourses.endPrice ? this.filteredCourses.endPrice : null,
            categoryIds: this.filteredCourses.categoryIds ? this.filteredCourses.categoryIds : [],
            sortId: this.filteredCourses.sortId ? this.filteredCourses.sortId : 0
          }
        });
  }
}
